import "./styles.css";

// No JS drives the dots or arrows — they're generated by ::scroll-marker/::scroll-button() in
// styles.css. This just reports whether the browser actually supports them.
const supportsScrollMarkers = CSS.supports("scroll-marker-group", "after");
console.log(`scroll-marker-group supported → ${supportsScrollMarkers}`);
if (!supportsScrollMarkers) {
  console.log("Falling back to a plain scroll-snap row — no dots, no generated arrows, still fully scrollable.");
}
